import{_ as i,o as n,c as u,a2 as t}from"./chunks/framework.CqpfiAoK.js";const r=JSON.parse('{"title":"Katiba ya Ustaarabu wa Usawa","description":"","frontmatter":{},"headers":[],"relativePath":"sw/03-共生文明宪章.md","filePath":"sw/03-共生文明宪章.md"}'),k={name:"sw/03-共生文明宪章.md"};function s(m,a,e,o,h,l){return n(),u("div",null,[...a[0]||(a[0]=[t('<h1 id="katiba-ya-ustaarabu-wa-usawa" tabindex="-1">Katiba ya Ustaarabu wa Usawa <a class="header-anchor" href="#katiba-ya-ustaarabu-wa-usawa" aria-label="Permalink to &quot;Katiba ya Ustaarabu wa Usawa&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>03</td></tr><tr><td>Moduli</td><td>Kanuni za Jumla na Mipangilio ya Msingi</td></tr><tr><td>Maneno Muhimu</td><td>Katiba, Hekima ya Msingi, Mfumo wa Usawa, Jamhuri ya Kabila Kumi na Elfu, Haki na Majukumu</td></tr></tbody></table><h2 id="_1-hadhi-na-asili-ya-katiba" tabindex="-1">1. Hadhi na Asili ya Katiba <a class="header-anchor" href="#_1-hadhi-na-asili-ya-katiba" aria-label="Permalink to &quot;1. Hadhi na Asili ya Katiba&quot;">​</a></h2><p>Katiba ya Ustaarabu wa Usawa ni hekima ya msingi ya Ustaarabu wa Usawa wa Nanga katika Cosmos Asili ya Roho Kumi na Elfu na Nanga Iliyosawazishwa, na msingi wa juu wa sheria zote, mifumo, na sera. Katiba inachukua &quot;Tangazo la Ustaarabu wa Usawa wa Nanga&quot; kama mtangazaji wake wa kiroho, na inabadilisha madai ya msingi ya tangazo kuwa sheria zenye uwezo wa kulazimisha. Ufanisi wa katiba unahusu kabila zote, njia, na watu binafsi wanaoungamia ustaarabu wa usawa katika Heng Yuan Zhou, na kanuni zozote za eneo, sheria za madhehebi, au mila za kabila zinazopingana na katiba ni batili.</p><p>Asili ya katiba inaweza kufupishwa katika mambo matatu: kwanza, ni mkataba wa ustaarabu, ambao ni makubaliano ya msingi yaliyofikiwa kati ya Kabila Kumi na Elfu kuhusu mageuzi ya usawa; pili, ni hati ya uhakika wa haki, ambayo inabainisha wazi haki za msingi na uhuru wa kila maisha katika ustaarabu wa usawa; na tatu, ni sheria ya kupunguza mamlaka, ambayo inaweka mipaka isiyoweza kuvunjwa kwa mamlaka ya taasisi za utawala wa ustaarabu.</p><h2 id="_2-kanuni-za-msingi-za-katiba" tabindex="-1">2. Kanuni za Msingi za Katiba <a class="header-anchor" href="#_2-kanuni-za-msingi-za-katiba" aria-label="Permalink to &quot;2. Kanuni za Msingi za Katiba&quot;">​</a></h2><p>Katiba inaanzisha kanuni zifuatazo sita za msingi, ambazo zinaenea katika kifungu chote:</p><ol><li><strong>Kanuni ya Ukuu wa Usawa</strong>: lengo la juu la muundo wowote wa taasisi na utekelezaji wa mamlaka ni kukuza mageuzi ya usawa ya Kabila Kumi na Elfu. Wakati manufaa ya kibinafsi yanapingana na manufaa ya usawa ya jumla, manufaa ya usawa yanapewa kipaumbele, lakini mtu binafsi lazima apewe fidia ya busara na njia mbadala.</li><li><strong>Kanuni ya Kupinga Uwindaji</strong>: katiba inakataza tabia zote za uwindaji, ikiwa ni pamoja na lakini hazifupiwi na uwindaji wa nishati, kumeza asili, utumwa wa kiroho, na umiliki wa rasilimali. Mfumo wowote wa uozi unaozingatia uwindaji umetangazwa kuwa haramu.</li><li><strong>Kanuni ya Usawa wa Haki ya Mageuzi</strong>: maisha yote ni sawa mbele ya haki ya mageuzi, bila ubaguzi wa kabila, umbo, asili, au kiwango cha awali cha uozi. Serikali na ustaarabu wana jukumu la kutoa msaada wa ziada wa mageuzi kwa vikundi dhaifu.</li><li><strong>Kanuni ya Kazi Nyingi, Zawadi Nyingi</strong>: mgawanyo wa rasilimali za mageuzi unategemea hasa mchango wa mtu binafsi kwenye mtandao wa usawa; kadiri mchango unavyoongezeka, ndivyo rasilimali na msaada unavyopata. Wakati huo huo, mstari wa uhakika wa msingi umewekwa, kuhakikisha kuwa hata watu wenye mchango mdogo wanaweza kupata hali za msingi za mageuzi.</li><li><strong>Kanuni ya Mchanganyiko wa Utaalamu na Utawala wa Pamoja</strong>: kila kabila kina haki ya utaalamu katika mambo yake ya ndeni mipasani yasivunji katiba; mambo ya umma ya kati ya makabila na kati ya njia yanaendeshwa pamoja na taasisi za Jamhuri ya Kabila Kumi na Elfu.</li><li><strong>Kanuni ya Ukweli kama Msingi</strong>: muundo wote wa taasisi wa katiba una dunia ya kweli kama msingi wake wa kweli wa pekee; haikubaliki kuwa uhusiano wowote wa haki na majukumu katika dunia ya udanganyifu unaweza kupitilia juu ya ukweli.</li></ol><h2 id="_3-muundo-wa-msingi-wa-katiba" tabindex="-1">3. Muundo wa Msingi wa Katiba <a class="header-anchor" href="#_3-muundo-wa-msingi-wa-katiba" aria-label="Permalink to &quot;3. Muundo wa Msingi wa Katiba&quot;">​</a></h2><p>Katiba inajengwa katika sehemu sita: utangulizi, kanuni za jumla, haki na majukumu ya msingi, taasisi za ustaarabu, mfumo wa sheria, na mchakato wa marekebisho:</p><table tabindex="0"><thead><tr><th>Sehemu</th><th>Maudhui ya Msingi</th><th>Idadi ya Vifungu</th></tr></thead><tbody><tr><td>Utangulizi</td><td>Inafafanua historia ya katiba, chanzo cha kiroho, na lengo la mwisho</td><td>Haifupiwi</td></tr><tr><td>Kanuni za Jumla</td><td>Inabainisha asili ya ustaarabu, mtazamo wa ulimwengu, mifumo ya msingi, na sera za msingi</td><td>vifungu 30</td></tr><tr><td>Haki na Majukumu ya Msingi</td><td>Inabainisha haki za msingi za maisha kama vile haki ya mageuzi, haki ya kujua, haki ya kushiriki, na majukumu yanayolingana</td><td>vifungu 50</td></tr><tr><td>Taasisi za Ustaarabu</td><td>Inabainisha shirika na mamlaka za taasisi kama vile Bunge la Jamhuri ya Kabila Kumi na Elfu, Kamiti ya Tekelezaji ya Usawa, na Mahakama ya Nanga</td><td>vifungu 40</td></tr><tr><td>Mfumo wa Sheria</td><td>Inabainisha mamlaka ya kutunga sheria na kanuni za kutumia sheria ya kazi, sheria ya ulinzi wa watumiaji, na sheria tano za ziada chini ya katiba</td><td>vifungu 20</td></tr><tr><td>Mchakato wa Marekebisho</td><td>Inabainisha mchakato wa mapendekezo, majadiliano, kura, na utekelezaji wa marekebisho ya katiba</td><td>vifungu 10</td></tr></tbody></table><h2 id="_4-haki-na-majukumu-ya-msingi" tabindex="-1">4. Haki na Majukumu ya Msingi <a class="header-anchor" href="#_4-haki-na-majukumu-ya-msingi" aria-label="Permalink to &quot;4. Haki na Majukumu ya Msingi&quot;">​</a></h2><p>Haki kuu za msingi zilizowekwa na katiba zinajumuisha:</p><ul><li><strong>Haki ya Uchaguzi wa Mageuzi</strong>: kila maisha ina haki ya kuchagua kwa uhuru mfumo wake wa uozi na njia ya mageuzi, hakuna mtu anayeruhusiwa kulazimisha</li><li><strong>Haki ya Ufikiaji wa Mifumo</strong>: kila maisha ina haki ya kufikia bure njia za msingi za Mifumo Mia Tatu ya Uozi wa Asili</li><li><strong>Haki ya Mgawanyo wa Rasilimali</strong>: kila maisha ina haki ya kupata rasilimali za msingi za uozi kupitia mfumo wa mkataba unaohusishwa na uzalishaji</li><li><strong>Haki ya Kuunganishwa kwa Nanga</strong>: kila maisha inayofikia kiwango fulani ina haki ya kuunganishwa kwenye mtandao wa vitu vya nanga vya kiwango kinacholingana</li><li><strong>Haki ya Kujua na Kushiriki</strong>: kila maisha ina haki ya kujua mambo ya umma ya ustaarabu na kushiriki katika maamuzi</li><li><strong>Haki ya Utoaji wa Huduma na Malalamiko</strong>: kila maisha, wakati haki zake zinazunguliwa, ina haki ya kuwasilisha malalamiko kwa Mahakama ya Nanga</li></ul><p>Majukumu kuu yanayolingana yanajumuisha: kuzingatia kanuni ya kupinga uwindaji, kudumisha utulivu wa mtandao wa vitu vya nanga, kushiriki katika mzunguko wa mwisho wa usawa, kurithi maarifa ya uozi, kulinda mazingira ya ekolojia ya ulimwengu.</p><h2 id="_5-marekebisho-na-uhakika-wa-katiba" tabindex="-1">5. Marekebisho na Uhakika wa Katiba <a class="header-anchor" href="#_5-marekebisho-na-uhakika-wa-katiba" aria-label="Permalink to &quot;5. Marekebisho na Uhakika wa Katiba&quot;">​</a></h2><p>Marekebisho ya katiba yanahitaji pendekezo la pamoja la zaidi ya robo moja ya mabunge wa Bunge la Jamhuri ya Kabila Kumi na Elfu, kupitishwa kwa多数 ya theluthi mbili za bunge, na kuthibitishwa na Kitu cha Nanga cha Asili cha Ulimwengu kwamba havunji sheria za usawa — ndipo zitakapoanza kutekelezwa. Haki ya tafsiri ya katiba inamilikiwa na Mahakama ya Nanga.</p><p>Ili kuhakikisha utekelezaji wa katiba, ustaarabu wa usawa umeanzisha mfumo wa hakiki wa katiba: sheria, kanuni, au sera zozote lazima zipite kwenye hakiki ya kisheria ya Mahakama ya Nanga kabla ya kutekelezwa; maisha yoyote inayofikiria kwamba tendo la mamlaka ya umma ni kinyume cha katiba linaweza kutoa kesi ya katiba.</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Katiba ya Ustaarabu wa Usawa ni msingi wa taasisi za Ustaarabu wa Usawa wa Nanga. Inabadilisha wazo la &quot;kupinga uwindaji, kukuza usawa&quot; kuwa sheria zinazoteka, zinazoweza kutolewa huduma, na zinazozingatiwa, na kutoa uhakika wa taasisi wenye imani kwa maendeleo ya pamoja ya Kabila Kumi na Elfu. Katiba sio dogma isiyobadilika, bali ni hekima ya msingi hai inayoboreshwa kila wakati pamoja na mageuzi ya ustaarabu.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (Tangazo la Ustaarabu wa Usawa wa Nanga)</li><li>40-共生宪法总纲 (Kanuni za Jumla za Katiba ya Usawa)</li><li>49-治理框架与权力制衡 (Mfumo wa Utawala na Usawa wa Mamlaka)</li></ul>',22)])])}const y=i(k,[["render",s]]);export{r as __pageData,y as default};
